use assets_manager::*;
use derive_more::*;
use std::ops::*;
use std::sync::*;
use crate::extensions::*;

/// A handle to an asset so that one can be shared by multiple entities.
/// `AssetCache` assets are loaded from a file on the disk and are stored in an
/// [`AssetCache`]. `Procedural` assets are those generated by code at runtime,
/// and are simply stored on the heap and referenced using [`Arc`]s.
/// 
/// In both cases, `T` is wrapped in [`MutableAsset`] to allow them to be
/// modified.
#[derive(From)]
pub enum AssetHandle<T> {
    /// A handle to a static asset that is stored in an [`AssetCache`].
    AssetCache(ArcHandle<MutableAsset<T>>),
    /// A handle to a dynamic asset that is stored on the heap.
    Procedural(Arc<MutableAsset<T>>)
}

impl<T> AssetHandle<T> {
    /// Locks this [`AssetHandle`] with read access, calls `f` on the contained
    /// value, and returns the returned value of `f`.
    pub fn read<R>(&self, f: impl FnOnce(&T) -> R) -> R {
        match self {
            Self::AssetCache(handle) => {
                f(&*handle.read().0.read_and_unwrap())
            },
            Self::Procedural(asset) => {
                f(&*asset.0.read_and_unwrap())
            }
        }
    }

    /// Locks this [`AssetHandle`] with write access, calls `f` on the contained
    /// value, and returns the returned value of `f`.
    pub fn write<R>(&self, f: impl FnOnce(&mut T) -> R) -> R {
        match self {
            Self::AssetCache(handle) => {
                f(&mut *handle.read().0.write_and_unwrap())
            },
            Self::Procedural(asset) => {
                f(&mut *asset.0.write_and_unwrap())
            }
        }
    }
}

/// A newtype pattern that wraps a [`RwLock`] so that [`Asset`] can be
/// implemented on it. This is used to allow [`Asset`]s to be modified.
pub struct MutableAsset<T>(pub RwLock<T>);

impl<A: Asset> Asset for MutableAsset<A> {
    const HOT_RELOADED: bool = A::HOT_RELOADED;

    fn load(cache: &AssetCache, id: &SharedString) -> Result<Self, BoxedError> {
        Ok(Self(RwLock::new(A::load(cache, id)?)))
    }
}
